import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { ArrowRight, Terminal } from "lucide-react";

export default function Home() {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { 
      opacity: 1, 
      transition: { staggerChildren: 0.2, delayChildren: 0.3 } 
    },
    exit: { opacity: 0, y: -20, transition: { duration: 0.3 } }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } }
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      exit="exit"
      className="min-h-screen flex flex-col justify-center items-center px-6 pt-20 relative overflow-hidden"
    >
      {/* Background glowing orbs */}
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-600/20 rounded-full blur-[120px] -z-10 pointer-events-none" />
      <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-purple-600/20 rounded-full blur-[120px] -z-10 pointer-events-none" />

      <div className="max-w-4xl w-full text-center z-10 flex flex-col items-center">

        <motion.div variants={itemVariants} className="mb-6 inline-flex items-center gap-2 px-4 py-2 rounded-full glass-panel border-purple-500/30 text-sm font-medium text-purple-300">
          <Terminal size={16} />
          <span>Hello World, I'm</span>
        </motion.div>

        <motion.h1 variants={itemVariants} className="text-5xl md:text-7xl lg:text-8xl font-black mb-6 tracking-tight">
          Aswitha V<br />
          <span className="text-gradient">Frontend Developer</span>
        </motion.h1>

        <motion.p variants={itemVariants} className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto mb-10 leading-relaxed">
          I craft responsive, dynamic, and visually stunning web applications. Currently building pixel-perfect experiences using React and modern CSS.
        </motion.p>

        <motion.div variants={itemVariants} className="flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center w-full">
          <Link to="/projects" className="group relative px-8 py-4 bg-white text-gray-950 font-bold rounded-xl overflow-hidden transition-all hover:scale-105 active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)] hover:shadow-[0_0_30px_rgba(255,255,255,0.5)] flex items-center justify-center gap-2">
            <span>View My Work</span>
            <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
          </Link>

          <Link to="/contact" className="px-8 py-4 glass-card font-bold rounded-xl hover:text-white transition-all hover:scale-105 active:scale-95 flex items-center justify-center">
            Let's Discuss
          </Link>
        </motion.div>

      </div>

      {/* Scroll Indicator */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.5, duration: 1 }}
        className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-gray-500"
      >
        <span className="text-xs uppercase tracking-widest">Scroll</span>
        <div className="w-0.5 h-12 bg-gradient-to-b from-gray-500 to-transparent rounded-full" />
      </motion.div>
    </motion.div>
  );
}

import { Link, useLocation } from "react-router-dom";
import { motion } from "framer-motion";
import { Code2, Github, Linkedin, Menu, X } from "lucide-react";
import { useState } from "react";

export default function Navbar() {
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);

  const navLinks = [
    { path: "/", name: "Home" },
    { path: "/skills", name: "Skills" },
    { path: "/projects", name: "Projects" },
    { path: "/about", name: "About" },
    { path: "/contact", name: "Contact" },
  ];

  return (
    <header className="fixed top-0 w-full z-50 glass-panel border-b border-gray-800">
      <div className="max-w-7xl mx-auto px-6 lg:px-12 h-20 flex items-center justify-between">

        {/* LOGO */}
        <Link to="/" className="flex items-center gap-2 group">
          <div className="p-2 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg group-hover:shadow-[0_0_15px_rgba(139,92,246,0.6)] transition-all duration-300">
            <Code2 size={24} className="text-white" />
          </div>
          <span className="text-2xl font-bold font-outfit text-white tracking-wide">
            Aswitha<span className="text-purple-500">.</span>
          </span>
        </Link>

        {/* DESKTOP NAV */}
        <nav className="hidden md:flex gap-8">
          {navLinks.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              className="relative text-sm font-medium tracking-wider uppercase text-gray-300 hover:text-white transition-colors py-2"
            >
              {link.name}
              {location.pathname === link.path && (
                <motion.div
                  layoutId="navbar-indicator"
                  className="absolute bottom-0 left-0 right-0 h-0.5 bg-gradient-to-r from-blue-400 to-purple-500 rounded-full"
                />
              )}
            </Link>
          ))}
        </nav>

        {/* SOCIALS & MOBILE TOGGLE */}
        <div className="flex items-center gap-4">
          <div className="hidden lg:flex items-center gap-4 border-l border-gray-700 pl-6 ml-2">
            <a href="https://github.com/aswithaa201" target="_blank" rel="noreferrer" className="text-gray-400 hover:text-white transition-colors">
              <Github size={20} />
            </a>
            <a href="https://www.linkedin.com/in/aswitha-v-76b5013aa" target="_blank" rel="noreferrer" className="text-gray-400 hover:text-[#0a66c2] transition-colors">
              <Linkedin size={20} />
            </a>
          </div>

          <button 
            className="md:hidden text-gray-300 hover:text-white p-2"
            onClick={() => setIsOpen(!isOpen)}
          >
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>
      </div>

      {/* MOBILE NAV MENU */}
      <motion.div
        initial={false}
        animate={{ height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }}
        className="md:hidden overflow-hidden bg-gray-900/95 backdrop-blur-xl border-b border-gray-800"
      >
        <div className="px-6 py-4 flex flex-col gap-4">
          {navLinks.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              onClick={() => setIsOpen(false)}
              className={`text-lg font-medium py-2 border-b border-gray-800 ${
                location.pathname === link.path ? "text-purple-400" : "text-gray-400"
              }`}
            >
              {link.name}
            </Link>
          ))}
          <div className="flex gap-4 pt-2 pb-4">
            <a href="https://github.com/aswithaa201" target="_blank" rel="noreferrer" className="text-gray-400 hover:text-white">
              <Github size={24} />
            </a>
            <a href="https://www.linkedin.com/in/aswitha-v-76b5013aa" target="_blank" rel="noreferrer" className="text-gray-400 hover:text-[#0a66c2]">
              <Linkedin size={24} />
            </a>
          </div>
        </div>
      </motion.div>
    </header>
  );
}

import { motion } from "framer-motion";
import { ExternalLink, Github, Layers } from "lucide-react";

export default function Projects() {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } },
    exit: { opacity: 0, y: -20, transition: { duration: 0.3 } }
  };

  const cardVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.5 } }
  };

  const projects = [
    {
      title: "E-Commerce Application",
      desc: "A fully functional modern e-commerce platform with product listing, cart system, and responsive design. Uses local storage for persistent cart state.",
      tech: ["React", "Tailwind CSS", "API", "Local Storage"],
      github: "https://github.com/aswithaa201",
      demo: "#",
      featured: true,
      color: "from-purple-500 to-indigo-600"
    },
    {
      title: "Task Management App",
      desc: "A sleek Todo application featuring real-time search, filtering capabilities, and dynamic state updates for efficient task tracking.",
      tech: ["React", "JavaScript", "CSS"],
      github: "https://github.com/aswithaa201",
      demo: "#",
      featured: false,
      color: "from-blue-500 to-cyan-500"
    },
    {
      title: "CRUD Dashboard",
      desc: "Administrative dashboard with full CRUD functionality, form handling, validation, and dynamic state updates.",
      tech: ["React", "Tailwind CSS"],
      github: "https://github.com/aswithaa201",
      demo: "#",
      featured: false,
      color: "from-emerald-500 to-teal-500"
    },
    {
      title: "Dynamic UI Components",
      desc: "A collection of highly reusable and accessible UI components like modals, sliders, and navigation bars built from scratch.",
      tech: ["React", "Framer Motion", "Tailwind CSS"],
      github: "https://github.com/aswithaa201",
      demo: "#",
      featured: false,
      color: "from-orange-500 to-red-500"
    }
  ];

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      exit="exit"
      className="min-h-screen pt-32 pb-20 px-6 max-w-7xl mx-auto"
    >
      <div className="mb-12 flex items-center gap-4">
        <Layers className="text-purple-500" size={32} />
        <h2 className="text-4xl md:text-5xl font-bold">Featured <span className="text-gradient">Projects</span></h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {projects.map((project, i) => (
          <motion.div 
            key={i} 
            variants={cardVariants}
            className={`glass-card p-6 flex flex-col group ${project.featured ? 'md:col-span-2 lg:col-span-2 relative overflow-hidden' : ''}`}
          >
            {project.featured && (
              <div className="absolute top-0 right-0 w-32 h-32 bg-purple-500/10 rounded-full blur-3xl -mr-10 -mt-10 transition-all group-hover:bg-purple-500/30" />
            )}

            <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${project.color} flex items-center justify-center mb-6 shadow-lg`}>
              <ExternalLink size={24} className="text-white" />
            </div>

            <h3 className="text-2xl font-bold mb-3">{project.title}</h3>
            <p className="text-gray-400 mb-6 flex-grow leading-relaxed">{project.desc}</p>

            <div className="flex flex-wrap gap-2 mb-6">
              {project.tech.map((t, idx) => (
                <span key={idx} className="px-3 py-1 bg-gray-800/50 border border-gray-700/50 rounded-full text-xs font-medium text-gray-300">
                  {t}
                </span>
              ))}
            </div>

            <div className="flex items-center gap-4 pt-4 border-t border-gray-800">
              <a href={project.github} target="_blank" rel="noreferrer" className="flex items-center gap-2 text-sm text-gray-400 hover:text-white transition-colors">
                <Github size={18} />
                <span>Source</span>
              </a>
              <a href={project.demo} className="flex items-center gap-2 text-sm text-purple-400 hover:text-purple-300 transition-colors ml-auto">
                <span>Live Preview</span>
                <ExternalLink size={16} />
              </a>
            </div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}

import { motion } from "framer-motion";
import { Cpu, Code, Database, LayoutTemplate, Smartphone, Zap } from "lucide-react";

export default function Skills() {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } },
    exit: { opacity: 0, y: -20, transition: { duration: 0.3 } }
  };

  const itemVariants = {
    hidden: { opacity: 0, scale: 0.8 },
    visible: { opacity: 1, scale: 1, transition: { type: "spring", stiffness: 100 } }
  };

  const skillCategories = [
    {
      title: "Frontend Core",
      icon: <LayoutTemplate className="text-blue-400" size={24} />,
      skills: ["React.js", "JavaScript (ES6+)", "HTML5", "CSS3"]
    },
    {
      title: "Styling & UI",
      icon: <Smartphone className="text-purple-400" size={24} />,
      skills: ["Tailwind CSS", "Framer Motion", "Responsive Design", "UI/UX Concepts"]
    },
    {
      title: "State & Data",
      icon: <Database className="text-emerald-400" size={24} />,
      skills: ["API Integration", "RESTful APIs", "Local Storage", "SQL"]
    },
    {
      title: "Tools & Perf",
      icon: <Zap className="text-yellow-400" size={24} />,
      skills: ["Git & GitHub", "Vite", "NPM/Yarn", "Performance Optimization"]
    }
  ];

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      exit="exit"
      className="min-h-screen pt-32 pb-20 px-6 max-w-7xl mx-auto flex flex-col justify-center"
    >
      <div className="mb-12 flex items-center gap-4">
        <Cpu className="text-blue-500" size={32} />
        <h2 className="text-4xl md:text-5xl font-bold">Technical <span className="text-gradient">Arsenal</span></h2>
      </div>

      <div className="grid md:grid-cols-2 gap-6 lg:gap-10">
        {skillCategories.map((category, idx) => (
          <motion.div key={idx} variants={itemVariants} className="glass-panel p-8 rounded-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity group-hover:scale-110 duration-500">
              {category.icon}
            </div>

            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-gray-800/50 rounded-xl border border-gray-700/50">
                {category.icon}
              </div>
              <h3 className="text-xl font-bold">{category.title}</h3>
            </div>

            <div className="flex flex-wrap gap-3">
              {category.skills.map((skill, i) => (
                <span key={i} className="px-4 py-2 bg-gray-800/80 border border-gray-700 hover:border-gray-500 rounded-lg text-sm font-medium text-gray-300 transition-colors shadow-sm">
                  {skill}
                </span>
              ))}
            </div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}
